function wooProductAnnounce({ product, chatId }) {
  if (
    !product ||
    typeof product !== "object" ||
    Array.isArray(product) ||
    typeof product.name !== "string" ||
    !product.name ||
    typeof product.permalink !== "string" ||
    !product.permalink
  )
    throw new Error("Product name and permalink are required.");
  if (
    !(typeof chatId === "string" && chatId.trim() && !chatId.startsWith("YOUR_")) &&
    !Number.isSafeInteger(chatId)
  )
    throw new Error("Set the Telegram chat ID.");
  const text =
    "✨ New Product Announcement ✨\nWe have just added " +
    product.name +
    ", Head to " +
    product.permalink +
    " to find out more.";
  return {
    product,
    chatId,
    text,
    html: text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"),
  };
}

return $input.all().map((item) => ({
  json: wooProductAnnounce({ product: item.json, chatId: "YOUR_TELEGRAM_CHAT_ID" }),
}));

return $input.all().map((item, index) => {
  if (typeof item.json.id !== "string" || !item.json.id)
    throw new Error("X post was not confirmed; inspect X before replaying.");
  return { json: item.json, pairedItem: { item: index } };
});

return $input.all().map((item, index) => {
  if (!Number.isSafeInteger(item.json.result?.message_id) || item.json.result.message_id <= 0)
    throw new Error("Telegram post was not confirmed; inspect both destinations before replaying.");
  return {
    json: {
      product: $("Prepare the announcement").item.json.product,
      tweet: $("Confirm the X post").item.json,
      telegram: item.json,
    },
    pairedItem: { item: index },
  };
});
